import math

def rope_wavelength(i: int, head_dim: int, base: int) -> float:
    """Positions needed for dimension pair i to complete one full 2*pi rotation."""
    return round(2 * math.pi * (base ** ((2 * i) / head_dim)), 1)

print(rope_wavelength(63, 128, 10000))

import math

def rope_wavelength(i: int, head_dim: int, base: int) -> float:
    return round(2 * math.pi * (base ** ((2 * i) / head_dim)), 1)

def fits_context(i: int, head_dim: int, base: int, context_len: int) -> bool:
    """Whether dimension pair i's wavelength avoids wrapping within context_len positions."""
    return rope_wavelength(i, head_dim, base) >= context_len

print(fits_context(63, 128, 10000, 100000))
print(fits_context(63, 128, 500000, 100000))
